/app/core/artwork/reader_resized_square_.content:
package artwork

import (
	"bytes"
	"image"
	"image/color"
	"image/jpeg"
	"testing"
)

func TestResizeImageSquare(t *testing.T) {
	source := image.NewRGBA(image.Rect(0, 0, 80, 40))
	for y := 0; y < 40; y++ {
		for x := 0; x < 80; x++ {
			source.Set(x, y, color.RGBA{R: 255, A: 255})
		}
	}
	var input bytes.Buffer
	if err := jpeg.Encode(&input, source, nil); err != nil {
		t.Fatal(err)
	}

	for _, tc := range []struct {
		name   string
		square bool
		width  int
		height int
		format string
	}{
		{name: "original shape", width: 40, height: 20, format: "jpeg"},
		{name: "square", square: true, width: 40, height: 40, format: "png"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			output, _, err := resizeImage(bytes.NewReader(input.Bytes()), 40, tc.square)
			if err != nil {
				t.Fatal(err)
			}
			decoded, format, err := image.Decode(output)
			if err != nil {
				t.Fatal(err)
			}
			if got := decoded.Bounds().Size(); got.X != tc.width || got.Y != tc.height || format != tc.format {
				t.Fatalf("got %dx%d %s, want %dx%d %s", got.X, got.Y, format, tc.width, tc.height, tc.format)
			}
		})
	}

	plain := &resizedArtworkReader{cacheKey: "cover", size: 40}
	square := &resizedArtworkReader{cacheKey: "cover", size: 40, square: true}
	if plain.Key() == square.Key() {
		t.Fatal("square and original shape share a cache key")
	}
}

